INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > MySQL > DML (Data Manipulation Language)
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wird mit INSERT in MySQL eine neue Zeile in eine Tabelle eingefügt?', 2, '[{"text": "Ja", "correct": true, "because": "INSERT fügt neue Datensätze hinzu"}, {"text": "Nein", "correct": false, "because": "Hauptzweck des Befehls"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann SELECT in MySQL Daten aus mehreren Tabellen gleichzeitig abrufen?', 2, '[{"text": "Ja", "correct": true, "because": "SELECT mit JOIN kombiniert Tabellen"}, {"text": "Nein", "correct": false, "because": "JOIN-Funktionalität vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Ändert UPDATE in MySQL bestehende Daten in einer Tabelle?', 2, '[{"text": "Ja", "correct": true, "because": "UPDATE modifiziert Datensätze"}, {"text": "Nein", "correct": false, "because": "Zweck ist Änderung"}]'),
('00000000-0000-0000-0000-000000000000', 'Löscht DELETE in MySQL alle Daten aus einer Tabelle ohne WHERE-Bedingung?', 2, '[{"text": "Ja", "correct": true, "because": "DELETE ohne WHERE löscht alles"}, {"text": "Nein", "correct": false, "because": "Standardverhalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Können INSERT und UPDATE in MySQL gleichzeitig in einem Befehl ausgeführt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Separate Befehle für separate Zwecke"}, {"text": "Ja", "correct": false, "because": "Nicht kombinierbar"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher DML-Befehl wird verwendet, um neue Daten in eine MySQL-Tabelle einzufügen?', 2, '[{"text": "INSERT", "correct": true, "because": "Fügt neue Datensätze hinzu"}, {"text": "SELECT", "correct": false, "because": "Abrufen von Daten"}, {"text": "UPDATE", "correct": false, "because": "Ändern von Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl in MySQL wird genutzt, um Daten aus einer Tabelle abzufragen?', 3, '[{"text": "SELECT", "correct": true, "because": "SELECT ruft Daten ab"}, {"text": "INSERT", "correct": false, "because": "Einfügen von Daten"}, {"text": "DELETE", "correct": false, "because": "Löschen von Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher DML-Befehl ändert bestehende Datensätze in einer MySQL-Tabelle?', 2, '[{"text": "UPDATE", "correct": true, "because": "Modifiziert vorhandene Daten"}, {"text": "INSERT", "correct": false, "because": "Fügt neue Daten hinzu"}, {"text": "DELETE", "correct": false, "because": "Entfernt Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl entfernt spezifische Zeilen aus einer MySQL-Tabelle?', 2, '[{"text": "DELETE", "correct": true, "because": "Entfernt Datensätze mit Bedingung"}, {"text": "SELECT", "correct": false, "because": "Abrufen, nicht löschen"}, {"text": "UPDATE", "correct": false, "because": "Ändern, nicht löschen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl kann mit einer WHERE-Klausel kombiniert werden, um gezielt Daten zu ändern?', 2, '[{"text": "UPDATE", "correct": true, "because": "Ändert spezifische Datensätze"}, {"text": "INSERT", "correct": false, "because": "Keine WHERE-Klausel"}, {"text": "CREATE", "correct": false, "because": "DDL, nicht DML"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche DML-Befehle gibt es in MySQL?', 4, '[{"text": "INSERT", "correct": true, "because": "Fügt Daten hinzu"}, {"text": "SELECT", "correct": true, "because": "Ruft Daten ab"}, {"text": "UPDATE", "correct": true, "because": "Ändert Daten"}, {"text": "CREATE", "correct": false, "because": "DDL, nicht DML"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operationen kann SELECT in MySQL ausführen?', 3, '[{"text": "Daten abrufen", "correct": true, "because": "Hauptfunktion"}, {"text": "Daten filtern", "correct": true, "because": "Mit WHERE möglich"}, {"text": "Tabellen verbinden", "correct": true, "because": "Mit JOIN möglich"}, {"text": "Tabellen erstellen", "correct": false, "because": "CREATE TABLE erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bedingungen können mit DELETE in MySQL verwendet werden?', 4, '[{"text": "WHERE", "correct": true, "because": "Spezifiziert zu löschende Zeilen"}, {"text": "ORDER BY", "correct": true, "because": "Sortiert vor Löschung"}, {"text": "LIMIT", "correct": true, "because": "Begrenzt Anzahl der Löschungen"}, {"text": "GROUP BY", "correct": false, "because": "Für Aggregation, nicht Löschung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat der INSERT-Befehl in MySQL?', 3, '[{"text": "Fügt neue Zeilen hinzu", "correct": true, "because": "Hauptfunktion"}, {"text": "Kann mehrere Zeilen einfügen", "correct": true, "because": "Mit mehreren Werten möglich"}, {"text": "Kann Spalten spezifizieren", "correct": true, "because": "Spaltenangabe optional"}, {"text": "Ändert bestehende Daten", "correct": false, "because": "UPDATE erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klauseln können mit UPDATE in MySQL kombiniert werden?', 3, '[{"text": "SET", "correct": true, "because": "Definiert Änderungen"}, {"text": "WHERE", "correct": true, "because": "Spezifiziert Zeilen"}, {"text": "LIMIT", "correct": true, "because": "Begrenzt Änderungen"}, {"text": "CREATE", "correct": false, "because": "DDL, nicht DML"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) INSERT fügt neue Daten in eine Tabelle ein. b) Es kann bestehende Daten ändern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einfügen ja, Ändern nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SELECT kann Daten aus mehreren Tabellen abrufen. b) DELETE löscht immer alle Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mehrere Tabellen ja, DELETE mit WHERE"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) UPDATE ändert bestehende Datensätze. b) Es kann neue Zeilen einfügen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ändern ja, Einfügen nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) DELETE kann mit WHERE gezielt Zeilen löschen. b) SELECT ändert Daten in der Tabelle.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gezielt löschen ja, SELECT ändert nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) INSERT kann mehrere Zeilen einfügen. b) UPDATE löscht Daten aus der Tabelle.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mehrere Zeilen ja, Löschen nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

